const subtitles={dashboard:'Your infrastructure, knowledge, and operations. Connected.',organizations:'Every client, location, and relationship in one workspace.',assets:'Track devices from purchase to retirement.',passwords:'Encrypted credentials, linked to the systems they unlock.',networks:'Document subnets, VLANs, gateways, and address allocations.',addresses:'Allocate IPv4 addresses without duplicates.',ports:'Document switch ports, uplinks, and physical connections.',racks:'Visualize server and network racks, unit by unit.',diagrams:'Map infrastructure, dependencies, and network traffic.',articles:'Make your team’s knowledge accessible and reusable.',procedures:'Repeatable checklists for reliable IT operations.',purchases:'Request, approve, order, and receive devices into inventory.',renewals:'Stay ahead of renewals, warranties, and documentation reviews.',reports:'Understand coverage, lifecycle, and operational workload.'};
let workspaceTimeZone='America/New_York';
let user=null,csrf='',records=[],favorites=[],page='dashboard',scope='',query='',filter='',pageNumber=1,dialogRecord=null,diagramDraft=null,diagramId='',selectedNode='',diagramDirty=false,secretTimer,searchTimer,searchRequest=0,priorFocus;
const writable=()=>['admin','editor'].includes(user?.role),admin=()=>user?.role==='admin';
const rec=id=>records.find(r=>r.id===id),ofType=t=>records.filter(r=>r.type===t),inScope=r=>!scope||r.orgId===scope||r.id===scope;
const title=id=>rec(id)?.name||'—', initials=s=>String(s||'').split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase();
const date=s=>s?new Date(s.includes('T')?s:s+'T12:00:00Z').toLocaleDateString(undefined,{timeZone:workspaceTimeZone,month:'short',day:'numeric',year:'numeric'}):'—';
const when=s=>new Date(s).toLocaleString(undefined,{timeZone:workspaceTimeZone});
const days=s=>{const today=new Intl.DateTimeFormat('en-CA',{timeZone:workspaceTimeZone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());return Math.round((new Date(s+'T12:00:00Z')-new Date(today+'T12:00:00Z'))/86400000)};
const money=(v,c='USD')=>{try{return new Intl.NumberFormat(undefined,{style:'currency',currency:c}).format(Number(v)||0)}catch{return `${c} ${Number(v)||0}`}};
function badge(s){const value=String(s||'—'),tone=/expired|revoked|overdue|retired|cancelled/i.test(value)?'red':/review|draft|submitted|pending|repair|progress|onboarding|reserved/i.test(value)?'warn':/ordered|dhcp|trial/i.test(value)?'blue':/inactive|not started/i.test(value)?'gray':'';return `<span class="pill ${tone}">${esc(value)}</span>`}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastId);window.toastId=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
async function api(path,method='GET',data){const response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},...(data!==undefined?{body:JSON.stringify(data)}:{})});let body;try{body=await response.json()}catch{throw Error('Server returned an invalid response')}if(!response.ok){if(response.status===401&&path==='/me')return null;throw Object.assign(Error(body.error||'Request failed'),{status:response.status})}return body}
function download(data,name,type='application/json'){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([data],{type}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
function empty(titleText,description='',type=''){return `<div class="empty">${icon(type||'articles')}<strong>${esc(titleText)}</strong>${esc(description)}${type&&writable()?`<div><button class="primary" data-act="new" data-type="${type}">${icon('plus')}Create first record</button></div>`:''}</div>`}
function modal(titleText,html,size=''){clearTimeout(secretTimer);priorFocus=document.activeElement;$('#dialog').className=size;$('#dialog').innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${esc(titleText)}</h2><button class="close" data-act="close" aria-label="Close dialog">×</button></div>${html}`;$('#overlay').hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('#dialog').querySelector('input,select,textarea,button')?.focus(),0)}
function close(){clearTimeout(secretTimer);$('#overlay').hidden=true;$('#dialog').innerHTML='';document.body.style.overflow='';dialogRecord=null;priorFocus?.focus()}
function errorIn(form,e){let el=form.querySelector('.form-error');if(!el){el=document.createElement('div');el.className='form-error';form.append(el)}el.textContent=e.message}
function heading(titleText,sub,actions=''){return `<div class="heading"><div><h1>${esc(titleText)}</h1><p class="subtitle">${esc(sub||'')}</p></div><div class="actions">${actions}</div></div>`}
function addButton(type,label='Add record'){return writable()?`<button class="primary" data-act="new" data-type="${type}">${icon('plus')}${label}</button>`:''}
function viewLink(p,text='View all'){return `<button class="text-button" data-page="${p}">${text}</button>`}
function panelHead(titleText,action='',sub=''){return `<div class="panel-head"><div><h2>${esc(titleText)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>${action}</div>`}
function authScreen(setup=false){$('#root').innerHTML=`<div class="auth-screen"><div class="auth-art"><div class="brand"><img src="/favicon.svg" alt=""><span>trinetra<small>IT DOCUMENTATION</small></span></div><div class="auth-copy"><div class="eyebrow">YOUR KNOWLEDGE. CONNECTED.</div><h1>Clarity for your<br><span>entire IT world.</span></h1><p>From a single credential to your entire network.<br>One place to document, connect, and understand<br>the systems your team depends on.</p></div><footer>Inventory · Networks · Knowledge · Operations</footer></div><div class="auth-form-wrap"><form id="auth-form" class="auth-form" data-setup="${setup}"><h2>${setup?'Create your workspace':'Welcome back'}</h2><p class="subtitle">${setup?'Set up your first administrator account.':'Sign in to your Trinetra workspace.'}</p>${setup?'<label class="form-field">Full name<input name="name" required autocomplete="name" maxlength="120"></label>':''}<label class="form-field">Email<input name="email" type="email" required autocomplete="username"></label><label class="form-field">Password<input name="password" type="password" required ${setup?'minlength="12"':''} maxlength="256" autocomplete="${setup?'new-password':'current-password'}"></label>${setup?'<small>Use at least 12 characters.</small><label class="check-label" style="margin-top:18px"><input name="samples" type="checkbox" checked>Include fictional example records</label>':'<label class="form-field">Authenticator code <small>(if MFA is enabled)</small><input name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}"></label>'}<button class="primary" type="submit">${setup?'Create workspace':'Sign in'}</button><div class="auth-foot">Your workspace is stored on this server. ${setup?'Keep the database and vault key backed up together.':'Sessions expire after eight hours.'}</div></form></div></div>`}
async function load(){records=await api('/records');favorites=await api('/favorites')}
function navigation(p){if(diagramDirty&&p!=='diagrams'){modal('Unsaved diagram changes','<p class="subtitle">Save your diagram before leaving, or discard the changes.</p><div class="form-actions"><button data-act="close">Keep editing</button><button data-act="discard-diagram" data-page-target="'+esc(p)+'">Discard changes</button><button class="primary" data-act="save-diagram">Save diagram</button></div>','small');return}page=p;query='';filter='';pageNumber=1;close();location.hash=p;render();document.body.classList.remove('menu-open')}
function shell(){const orgs=ofType('organizations');$('#root').innerHTML=`<aside class="sidebar"><a href="#dashboard" class="brand" data-page="dashboard"><img src="/favicon.svg" alt=""><span>trinetra<small>IT DOCUMENTATION</small></span></a><div class="scope-card"><span class="scope-icon">${icon('organizations')}</span><div>${user.role==='client'?'Client workspace':'IT Operations'}<small>${esc(user.role==='client'?'Your shared documentation':'Connected documentation')}</small></div></div><div class="nav-scroll">${groups.map(([label,pages])=>{const items=pages.filter(p=>!(['users','activity'].includes(p)&&!admin())&&!(p==='trash'&&!writable())&&!(user.role==='client'&&['passwords','purchases','vendors','templates','reports'].includes(p)));return items.length?`<div class="nav-group">${label}</div>${items.map(p=>`<a class="nav-link ${page===p?'active':''}" href="#${p}" data-page="${p}">${icon(p)}${names[p]}${p==='renewals'&&expirations().length?`<span class="count">${expirations().length}</span>`:''}</a>`).join('')}`:''}).join('')}</div><div class="sidebar-bottom"><div class="profile"><span class="avatar">${esc(initials(user.name))}</span><span>${esc(user.name)}<small>${esc(user.role==='client'?'Client access':user.role+' access')}</small></span><button class="icon-button" data-act="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="app"><header class="topbar"><button class="icon-button mobile-menu" data-act="menu" aria-label="Toggle navigation">☰</button><div class="breadcrumbs">Workspace<span>/</span><b id="crumb">${names[page]}</b></div><div class="top-actions"><div class="searchbox">${icon('search')}<input id="global-search" aria-label="Search workspace" placeholder="Search your workspace…" autocomplete="off"><kbd>Ctrl K</kbd></div><select id="scope" class="org-scope" aria-label="Organization scope"><option value="">All organizations</option>${orgs.map(o=>`<option value="${o.id}" ${scope===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select>${user.role==='client'?'<span class="client-indicator">Client</span>':`<span class="avatar">${esc(initials(user.name))}</span>`}</div><div id="search-results" hidden></div></header><main id="main"></main><footer class="footer"><span>Trinetra IT · Self-hosted workspace</span><span>Knowledge that keeps your team moving.</span></footer></div>`}
function organizationCoverage(o){const linked=records.filter(r=>r.orgId===o.id);const categories=['assets','articles','passwords','networks','contacts'];return Math.round(categories.filter(t=>linked.some(r=>r.type===t)).length/categories.length*100)}
function stat(label,value,type,note){return `<div class="stat"><label>${label}</label><span class="stat-icon">${icon(type)}</span><strong>${value}</strong><small>${note}</small></div>`}
function organizationTable(rows,limit){rows=limit?rows.slice(0,limit):rows;return `<div class="table-scroll"><table><thead><tr><th>Organization</th><th>Assets</th><th>Coverage</th><th>Status</th></tr></thead><tbody>${rows.map(o=>`<tr data-record="${o.id}" tabindex="0"><td><div class="record-name"><span class="initials">${esc(initials(o.name))}</span><div><strong>${esc(o.name)}</strong><small>${esc(o.domain||'Organization')}</small></div></div></td><td>${records.filter(r=>r.orgId===o.id&&r.type==='assets').length}</td><td><div class="coverage"><span class="bar"><i style="width:${organizationCoverage(o)}%"></i></span>${organizationCoverage(o)}%</div></td><td>${badge(o.status)}</td></tr>`).join('')}</tbody></table></div>`}
function expirations(){return records.filter(inScope).flatMap(r=>[...(r.expires?[{r,date:r.expires,kind:'Expiration'}]:[]),...(r.reviewDate?[{r,date:r.reviewDate,kind:'Review'}]:[])]).filter(v=>days(v.date)<=90).sort((a,b)=>a.date.localeCompare(b.date))}
function dashboard(){const scoped=records.filter(inScope),orgs=ofType('organizations').filter(inScope),health=orgs.length?Math.round(orgs.reduce((n,o)=>n+organizationCoverage(o),0)/orgs.length):0;const renewals=expirations();return heading('Workspace overview',subtitles.dashboard,addButton('articles','Create new'))+`<div class="hero"><div><span class="eyebrow">A CLEARER PICTURE OF YOUR IT</span><h2>Everything connected. Nothing overlooked.</h2><p>Your devices, networks, credentials, and team knowledge — organized around the organizations you support.</p></div><button data-page="diagrams">${icon('diagrams')}Explore your infrastructure</button></div><div class="stats">${stat('Organizations',orgs.length,'organizations','Client environments, connected')}${stat('Documented assets',scoped.filter(r=>r.type==='assets').length,'assets','Inventory across your workspace')}${stat('Knowledge articles',scoped.filter(r=>r.type==='articles').length,'articles','Answers for your entire team')}${stat('Upcoming expirations',renewals.length,'renewals','Due or overdue within 90 days')}</div><div class="dashboard-grid"><div><div class="panel">${panelHead('Your organizations',viewLink('organizations'))}${orgs.length?organizationTable(orgs,5):empty('Start with an organization','Build your documentation around the clients you support.','organizations')}<div class="table-foot"><span>${orgs.length} organizations in this view</span><span>Coverage across 5 core documentation types</span></div></div><div class="panel">${panelHead('Quick actions')}<div class="quick-actions">${[['assets','Add device'],['articles','Write an article'],['networks','Document network'],['purchases','Create purchase order']].filter(([t])=>user.role!=='client'||t==='articles').map(([t,label])=>`<button ${writable()?`data-act="new" data-type="${t}"`:`data-page="${t}"`}>${icon(t)}${label}</button>`).join('')}</div></div><div class="panel">${panelHead('Recently updated documentation',viewLink('articles'))}${scoped.filter(r=>r.type==='articles').length?`<div class="mini-list">${scoped.filter(r=>r.type==='articles').slice(0,4).map(r=>`<div class="mini-item"><span class="mini-icon">${icon('articles')}</span><div><strong>${esc(r.name)}</strong><small>${esc(title(r.orgId))} · ${date(r.updated)}</small></div><button class="text-button" data-record="${r.id}">Open</button></div>`).join('')}</div>`:empty('No articles yet','Document a process or troubleshooting guide.','articles')}</div></div><div class="right-column"><div class="panel">${panelHead('Documentation coverage')}<div class="health"><div class="health-ring" style="--progress:${health}%"><div><strong>${health}%</strong><small>Overall coverage</small></div></div><div class="health-copy"><strong>${health>=80?'Well documented':health?'Room to grow':'Start documenting'}</strong><p>Connect assets, networks,<br>contacts, articles, and credentials.</p></div></div><div class="panel-note">Calculated from records in each organization</div></div><div class="panel">${panelHead('Expirations & reviews',viewLink('renewals'))}<div class="mini-list">${renewals.slice(0,4).map(v=>`<div class="mini-item"><span class="mini-icon">${icon(v.r.type)}</span><div><strong>${esc(v.r.name)}</strong><small>${esc(title(v.r.orgId))}</small>${badge(days(v.date)<0?`${Math.abs(days(v.date))} days overdue`:`${days(v.date)} days remaining`)}</div><button class="text-button" data-record="${v.r.id}">⋯</button></div>`).join('')||'<p class="muted" style="font-size:13px;padding:10px 0">No upcoming expirations.</p>'}</div></div><div class="panel">${panelHead('Connected infrastructure',viewLink('diagrams'))}${ofType('diagrams').filter(inScope)[0]?`<div class="diagram-preview">${svgDiagram(ofType('diagrams').filter(inScope)[0],false)}</div><div class="panel-note">${esc(ofType('diagrams').filter(inScope)[0].name)}</div>`:empty('Map your network','Create diagrams with linked inventory devices.','diagrams')}</div></div></div>`}
function listRows(type){return ofType(type).filter(inScope).filter(r=>!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase())).filter(r=>!filter||r.status===filter)}
function tools(type,rows){const statuses=[...new Set(ofType(type).map(r=>r.status).filter(Boolean))];return `<div class="table-tools"><input id="list-search" aria-label="Search records" placeholder="Search ${names[type].toLowerCase()}…" value="${esc(query)}"><div class="actions">${statuses.length?`<select id="status-filter" aria-label="Filter by status"><option value="">All statuses</option>${statuses.map(s=>`<option ${filter===s?'selected':''}>${esc(s)}</option>`).join('')}</select>`:''}<span class="muted" style="font-size:12px">${rows.length} records</span></div></div>`}
function cell(r,key){const value=r[key];if(key==='status')return badge(value);if(key.endsWith('Id'))return esc(title(value));if(['expires','purchaseDate','reviewDate'].includes(key))return esc(date(value));if(key==='total')return money(r.quantity*r.unitCost,r.currency);if(key==='fieldCount')return r.fields?.length||0;if(key==='completion')return `${(r.steps||[]).filter(s=>s.done).length} / ${(r.steps||[]).length} steps`;return esc(value||'—')}
function tableBody(type,rows){const cols=columns[type]||[];return `<div class="table-scroll"><table><thead><tr><th>Name</th>${!scope?'<th>Organization</th>':''}${cols.map(([,label])=>`<th>${label}</th>`).join('')}<th>Updated</th></tr></thead><tbody>${rows.map(r=>`<tr data-record="${r.id}" tabindex="0"><td><strong>${esc(r.name)}</strong>${type==='passwords'?'<small>••••••••••••</small>':''}</td>${!scope?`<td>${esc(title(r.orgId))}</td>`:''}${cols.map(([key])=>`<td>${cell(r,key)}</td>`).join('')}<td>${esc(date(r.updated))}</td></tr>`).join('')}</tbody></table></div>`}
function listPage(type){const rows=listRows(type),totalPages=Math.max(1,Math.ceil(rows.length/30));pageNumber=Math.min(pageNumber,totalPages);const visible=rows.slice((pageNumber-1)*30,pageNumber*30);const actions=`${writable()&&type!=='passwords'?`<button data-act="import" data-type="${type}">${icon('download')}Import CSV</button>`:''}<button data-act="csv" data-type="${type}">${icon('download')}Export</button>${addButton(type,type==='organizations'?'Add organization':type==='articles'?'New article':type==='passwords'?'Add credential':type==='purchases'?'New purchase order':'Add record')}`;let content=heading(names[type],subtitles[type]||`Manage ${names[type].toLowerCase()} and their linked documentation.`,actions);if(type==='passwords')content+='<div class="notice">Vault secrets are encrypted at rest. Revealing a credential requires your account password and authenticator code if MFA is enabled. Secret access is audited.</div>';if(type==='articles'){return content+`<div class="panel">${panelHead('Articles',`<span class="muted" style="font-size:12px">Markdown · History · Attachments</span>`)}${tools(type,rows)}</div>${visible.length?`<div class="cards">${visible.map(r=>`<article class="doc-card" data-record="${r.id}" tabindex="0"><div class="card-meta">${icon(type)}${badge(r.status)}</div><h3>${esc(r.name)}</h3><p>${esc((r.content||r.notes||'').replace(/[#*`]/g,'').slice(0,150))}…</p><small>${esc(title(r.orgId))} · ${esc(r.category||'General')}</small></article>`).join('')}</div>`:empty('No matching articles','Try a different search, or create a new article.',type)}${pagination(rows.length,totalPages)}`}
 return content+`<div class="panel">${panelHead(names[type])}${tools(type,rows)}${rows.length?(type==='organizations'?organizationTable(visible):tableBody(type,visible)):empty(query?'No matching records':'No records yet','Create a record to get started.',type)}${pagination(rows.length,totalPages)}</div>`}
function pagination(total,pages){return `<div class="table-foot"><span>${total} records · Page ${pageNumber} of ${pages}</span><div class="table-pagination"><button data-act="prev" ${pageNumber===1?'disabled':''}>Previous</button><button data-act="next" ${pageNumber>=pages?'disabled':''}>Next</button></div></div>`}
function expirationPage(){const rows=expirations().filter(v=>!query||(v.r.name+' '+title(v.r.orgId)).toLowerCase().includes(query.toLowerCase()));return heading('Expirations & reviews',subtitles.renewals)+`<div class="panel">${panelHead('Next 90 days & overdue records')}<div class="table-tools"><input id="list-search" aria-label="Search records" placeholder="Search expirations…" value="${esc(query)}"></div><div class="table-scroll"><table><thead><tr><th>Record</th><th>Organization</th><th>Category</th><th>Due date</th><th>Time remaining</th></tr></thead><tbody>${rows.map(v=>`<tr data-record="${v.r.id}" tabindex="0"><td><strong>${esc(v.r.name)}</strong></td><td>${esc(title(v.r.orgId))}</td><td>${names[v.r.type]} · ${v.kind}</td><td>${date(v.date)}</td><td>${badge(days(v.date)<0?`${-days(v.date)} days overdue`:`${days(v.date)} days`)}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('No records due soon','Expiration dates and review dates will appear here.')}</div>`}
function rackPage(){const racks=listRows('racks');return heading('Rack management',subtitles.racks,addButton('racks','Add rack'))+(racks.length?`<div class="rack-grid">${racks.map(r=>{const assets=ofType('assets').filter(a=>a.rackId===r.id),used=assets.reduce((n,a)=>n+Number(a.rackUnits),0);return `<section class="rack-card"><div class="rack-title"><div><h3>${esc(r.name)}</h3><small>${esc(title(r.orgId))} · ${esc(title(r.locationId))}</small></div><button class="icon-button" data-record="${r.id}" aria-label="Rack details">${icon('edit')}</button></div><div class="rack" style="grid-template-rows:repeat(${r.units},24px)">${Array.from({length:r.units},(_,n)=>{const unit=r.units-n;return `<span class="rack-unit" style="grid-row:${n+1}">${unit}</span><span class="rack-slot" style="grid-row:${n+1}"></span>`}).join('')}${assets.map(a=>`<button class="rack-device ${a.category==='Server'?'server':a.category==='Firewall'?'firewall':''}" style="grid-row:${r.units-Number(a.rackStart)-Number(a.rackUnits)+2}/span ${Number(a.rackUnits)}" data-record="${a.id}" title="${esc(a.name)} · U${a.rackStart}–${Number(a.rackStart)+Number(a.rackUnits)-1}"><span>${esc(a.name)}</span><span class="lights">•••</span></button>`).join('')}</div><div class="rack-foot"><span>${used} / ${r.units} U occupied</span><span>${Math.round(used/r.units*100)}% utilization</span></div>${writable()?`<button class="text-button" style="margin-top:12px;font-size:12px" data-act="rack-asset" data-id="${r.id}">+ Place a device</button>`:''}</section>`}).join('')}</div>`:empty('Create your first rack','Place inventory devices in rack units with overlap validation.','racks'))}
function svgDiagram(d,editable=true){const nodes=d.nodes||[],edges=d.edges||[],maxX=Math.max(1100,...nodes.map(n=>n.x+210)),maxY=Math.max(560,...nodes.map(n=>n.y+130));return `<svg ${editable?'id="diagram-svg"':''} class="${editable?'diagram-canvas':''}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${maxX} ${maxY}" role="img" aria-label="${esc(d.name)}"><defs><marker id="edge-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 10 5 0 10z" fill="#8aa6b3"/></marker></defs>${edges.map(e=>{const a=nodes.find(n=>n.id===e.from),b=nodes.find(n=>n.id===e.to);if(!a||!b)return '';return `<g class="edge"><path d="M${a.x+160} ${a.y+39} C${a.x+210} ${a.y+39},${b.x-50} ${b.y+39},${b.x} ${b.y+39}" fill="none" stroke="#94adb8" stroke-width="1.6" marker-end="url(#edge-arrow)"/><text x="${(a.x+160+b.x)/2}" y="${(a.y+b.y)/2+22}" text-anchor="middle" fill="#8199a9" font-family="Segoe UI,sans-serif" font-size="10">${esc(e.label)}</text></g>`}).join('')}${nodes.map(n=>`<g class="node ${selectedNode===n.id?'selected':''}" ${editable?`data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="Select ${esc(n.label)}"`:''} transform="translate(${n.x},${n.y})"><rect width="160" height="78" rx="8" fill="white" stroke="#bdcfd8"/><rect x="12" y="15" width="30" height="30" rx="7" fill="#e4f1eb" stroke="none"/><text x="27" y="36" text-anchor="middle" fill="#63937e" font-size="17">${n.kind==='cloud'?'☁':n.kind==='server'?'▤':n.kind==='firewall'?'▦':'◇'}</text><text x="52" y="30" font-family="Segoe UI,sans-serif" font-size="12" fill="#426174">${esc(n.label.slice(0,17))}</text><text class="node-kind" x="52" y="48" font-family="Segoe UI,sans-serif" font-size="9" fill="#829dab">${esc(n.kind||'device')}</text><text x="14" y="66" font-family="Segoe UI,sans-serif" font-size="9" fill="#829dab">${n.assetId?'Linked inventory asset':'Diagram component'}</text></g>`).join('')}</svg>`}
function diagramPage(){const diagrams=ofType('diagrams').filter(inScope);if(!diagramDraft||!diagrams.some(d=>d.id===diagramId)){diagramDraft=diagrams[0]?structuredClone(diagrams[0]):null;diagramId=diagramDraft?.id||'';selectedNode='';diagramDirty=false}return heading('Infrastructure diagrams',subtitles.diagrams,addButton('diagrams','New diagram'))+(diagramDraft?`<div class="diagram-toolbar"><select id="diagram-select" aria-label="Select diagram">${diagrams.map(d=>`<option value="${d.id}" ${d.id===diagramId?'selected':''}>${esc(d.name)}</option>`).join('')}</select>${writable()?'<button class="primary" data-act="save-diagram">'+icon('save')+'Save diagram</button>':''}<button data-act="svg-export">${icon('download')}Export SVG</button><button data-record="${diagramId}">Details</button><span id="diagram-save-status" class="muted" style="font-size:12px">${diagramDirty?'Unsaved changes':'All changes saved'}</span></div><div class="diagram-layout"><div class="diagram-wrap">${svgDiagram(diagramDraft)}</div><div>${diagramSide()}</div></div>`:empty('Draw your first diagram','Add connected devices and label network flows.','diagrams'))}
function diagramSide(){const n=diagramDraft?.nodes.find(n=>n.id===selectedNode);return `<div class="panel diagram-side"><h3>${n?'Selected component':'Diagram tools'}</h3><small>${writable()?'Drag components to arrange the diagram. Select one to edit its label or link an inventory asset.':'View the documented topology and export a diagram.'}</small>${writable()?`<form id="node-form"><label class="form-field">Component label<input name="label" required maxlength="100" value="${esc(n?.label||'')}"></label><label class="form-field">Type<select name="kind">${['device','cloud','firewall','switch','server','workstation','service'].map(v=>`<option ${n?.kind===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="form-field">Inventory asset<select name="assetId"><option value="">Standalone component</option>${ofType('assets').filter(a=>a.orgId===diagramDraft.orgId).map(a=>`<option value="${a.id}" ${n?.assetId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><button type="submit" class="primary">${n?'Update component':'Add component'}</button></form>${n?'<button data-act="remove-node" class="danger">Remove component</button><button data-act="deselect-node">Add a different component</button>':''}<div class="detail-section"><h3>Add a connection</h3><form id="edge-form"><label class="form-field">From<select name="from" required><option value="">Choose component</option>${diagramDraft.nodes.map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('')}</select></label><label class="form-field">To<select name="to" required><option value="">Choose component</option>${diagramDraft.nodes.map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('')}</select></label><label class="form-field">Protocol / flow label<input name="label" maxlength="100" placeholder="HTTPS · TCP 443"></label><button type="submit">Connect components</button></form></div><div class="detail-section"><h3>Connections</h3>${diagramDraft.edges.map((e,i)=>`<div style="display:flex;gap:7px;font-size:11px;margin-bottom:8px"><span style="flex:1">${esc(diagramDraft.nodes.find(n=>n.id===e.from)?.label)} / ${esc(diagramDraft.nodes.find(n=>n.id===e.to)?.label)}<small>${esc(e.label)}</small></span><button class="icon-button danger" style="width:auto" data-act="remove-edge" data-index="${i}" aria-label="Remove connection">×</button></div>`).join('')||'<small>No connections yet.</small>'}</div>`:''}</div>`}
function reportPage(){const scoped=records.filter(inScope),assets=scoped.filter(r=>r.type==='assets'),groupBy=(rows,key)=>rows.reduce((a,r)=>(a[r[key]||'Unspecified']=(a[r[key]||'Unspecified']||0)+1,a),{});const chart=(titleText,groups,total)=>`<div class="panel"><h2>${titleText}</h2>${Object.entries(groups).map(([k,v])=>`<div class="report-line"><span>${esc(k)}</span><b>${v}</b></div><div class="progress-line"><i style="width:${total?v/total*100:0}%"></i></div>`).join('')||'<p class="muted">No records yet.</p>'}</div>`;return heading('Documentation & operations reports',subtitles.reports,`<button data-act="report-export">${icon('download')}Export report</button>`)+`<div class="stats">${stat('Inventory value',money(assets.reduce((n,a)=>n+Number(a.cost||0),0)),'assets','Recorded costs · see currency per device')}${stat('Open purchase orders',scoped.filter(r=>r.type==='purchases'&&!['Received','Cancelled'].includes(r.status)).length,'purchases','Draft through ordered')}${stat('Articles needing review',scoped.filter(r=>r.type==='articles'&&r.reviewDate&&days(r.reviewDate)<=0).length,'articles','Review dates today or overdue')}${stat('License seats available',scoped.filter(r=>r.type==='licenses').reduce((n,r)=>n+Math.max(0,Number(r.quantity||0)-Number(r.assigned||0)),0),'licenses','Purchased less assigned seats')}</div><div class="report-grid">${chart('Asset lifecycle',groupBy(assets,'status'),assets.length)}${chart('Inventory by device type',groupBy(assets,'category'),assets.length)}${chart('Records by organization',scoped.filter(r=>r.type==='organizations').reduce((a,o)=>(a[o.name]=scoped.filter(r=>r.orgId===o.id).length,a),{}),scoped.length)}<div class="panel"><h2>Rack utilization</h2>${scoped.filter(r=>r.type==='racks').map(r=>{const used=assets.filter(a=>a.rackId===r.id).reduce((n,a)=>n+Number(a.rackUnits),0);return `<div class="report-line"><span>${esc(r.name)}</span><b>${used} / ${r.units} U</b></div><div class="progress-line"><i style="width:${used/r.units*100}%"></i></div>`}).join('')||'<p class="muted">No racks documented.</p>'}</div></div>`}
function settingsPage(){return heading('Settings & integrations','Manage account security, API access, and documentation exports.')+`<div class="settings-grid"><div class="panel"><h2>Your account</h2><p>${esc(user.name)}<br>${esc(user.email)}<br>${esc(user.role)} access</p><button data-act="change-password">Change password</button><h3 style="margin-top:25px">Authenticator MFA</h3><p>${user.mfa?'MFA is enabled for your account.':'Add a six-digit authenticator code to protect sign-in and vault access.'}</p><button data-act="mfa">${user.mfa?'Disable MFA':'Set up authenticator'}</button></div><div class="panel"><h2>Documentation export</h2><p>Download organization documentation as JSON. Credentials, user accounts, and file attachment contents are excluded. Use a server backup for complete recovery.</p>${user.role!=='client'?'<button data-act="export">'+icon('download')+'Export documentation</button>':''}<h3 style="margin-top:25px">Server backups</h3><p>Stop the server, then back up the complete data directory. The database and vault key must be restored together. See README for commands and recovery guidance.</p></div>${admin()?'<div class="panel"><h2>Read-only API access</h2><p>Create a revocable, 30-day API token to read documentation from external tools. Secrets cannot be revealed through API tokens.</p><button data-act="tokens">Manage API tokens</button><div class="code-block" style="margin-top:18px">GET /api/records?type=assets<br>Authorization: Bearer &lt;token&gt;</div></div>':''}<div class="panel"><h2>Integration boundaries</h2><p>CSV import/export and a read-only JSON API are available. Vendor-specific PSA/RMM/cloud synchronization, discovery agents, automated live certificate checks, SSO, browser extensions, and email delivery are not connected in this release.</p><p>Expirations use the dates you document. Network maps show saved documentation, not live network discovery.</p></div></div>`}
async function render(){shell();const main=$('#main');if(schema[page]&&!['racks','diagrams'].includes(page))main.innerHTML=listPage(page);else if(page==='dashboard')main.innerHTML=dashboard();else if(page==='renewals')main.innerHTML=expirationPage();else if(page==='racks')main.innerHTML=rackPage();else if(page==='diagrams'){main.innerHTML=diagramPage();bindDiagramDrag()}else if(page==='reports')main.innerHTML=reportPage();else if(page==='settings')main.innerHTML=settingsPage();else if(page==='favorites')main.innerHTML=heading('Favorites','Keep your most useful documentation close.')+`<div class="cards">${favorites.filter(inScope).map(r=>`<article class="doc-card" data-record="${r.id}" tabindex="0">${icon(r.type)}<h3>${esc(r.name)}</h3><small>${names[r.type]} · ${esc(title(r.orgId))}</small></article>`).join('')||empty('No favorites yet','Open a record and select Favorite.')}</div>`;else if(page==='trash'){main.innerHTML=heading('Recycle bin','Restore deleted records. Linked records are validated before recovery.');try{const rows=await api('/trash');if(page!=='trash')return;main.innerHTML+=`<div class="panel"><div class="mini-list">${rows.map(r=>`<div class="mini-item"><div><strong>${esc(r.name)}</strong><small>${names[r.type]} · ${when(r.deleted)}</small></div><button data-act="restore" data-id="${r.id}">Restore</button></div>`).join('')||empty('Recycle bin is empty')}</div></div>`}catch(e){main.innerHTML+=empty(e.message)}}else if(page==='users')await usersPage();else if(page==='activity')await auditPage();else main.innerHTML=empty('Page unavailable')}
async function usersPage(){if(!admin()){$('#main').innerHTML=empty('Administrator access required');return}const rows=await api('/users');if(page!=='users')return;$('#main').innerHTML=heading('Users & access','Control workspace roles and organization-level access.',`<button class="primary" data-act="new-user">${icon('plus')}Add user</button>`)+`<div class="notice">Administrators manage the whole workspace. Editors can update assigned organizations. Viewers can read documentation but cannot reveal secrets. Clients see only assigned organizations and records explicitly marked “Client visible”.</div><div class="panel"><div class="table-scroll"><table><thead><tr><th>User</th><th>Role</th><th>Organization access</th><th>MFA</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${esc(u.role)}</td><td>${u.orgs.length?u.orgs.map(title).map(esc).join(', '):'All organizations'}</td><td>${u.mfa?'Enabled':'Not enabled'}</td><td>${badge(u.active?'Active':'Inactive')}</td><td><button data-act="edit-user" data-id="${u.id}">Edit access</button></td></tr>`).join('')}</tbody></table></div></div>`;window.managedUsers=rows}
async function auditPage(){if(!admin()){$('#main').innerHTML=empty('Administrator access required');return}const rows=await api('/audit');if(page!=='activity')return;window.auditRows=rows;$('#main').innerHTML=heading('Audit log','Server-recorded changes, sign-ins, and secret access. Most recent 1,000 events.',`<button data-act="audit-export">${icon('download')}Export audit</button>`)+`<div class="panel"><div class="table-scroll"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(when(r.time))}</td><td>${esc(r.actor)}</td><td>${esc(r.action.replaceAll('_',' '))}</td><td>${esc(title(r.target)||r.target)}</td><td>${esc(r.details)}</td></tr>`).join('')}</tbody></table></div></div>`}
function fieldHtml(f,r,type){let value=r[f.key]??'',control;const required=f.required?'required':'';if(f.kind==='ref'){const options=ofType(f.ref).filter(v=>!v.orgId||v.orgId===(r.orgId||scope));control=`<select name="${f.key}" ${required}><option value="">Select ${esc(f.label.toLowerCase())}</option>${options.map(v=>`<option value="${v.id}" ${value===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select>`}else if(f.kind==='select'){control=`<select name="${f.key}">${f.options.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`}else if(['textarea','steps','lines'].includes(f.kind)){if(f.kind==='steps')value=(r.steps||[]).map(s=>s.text).join('\n');if(f.kind==='lines')value=(r.fields||[]).join('\n');control=`<textarea name="${f.key}" ${required} ${f.key==='content'?'style="min-height:270px"':''} maxlength="30000">${esc(value)}</textarea>`}else{if(f.kind==='password')value='';control=`<input name="${f.key}" type="${f.kind}" value="${esc(value)}" ${required} ${f.kind==='number'?'min="0" step="any"':''} maxlength="${f.kind==='password'?'4096':'1000'}" placeholder="${esc(f.placeholder||'')}" ${f.kind==='password'?'autocomplete="new-password"':''}>`;if(f.key==='password')control=`<div class="password-controls">${control}<button type="button" data-act="generate">Generate</button></div>`}return `<label class="form-field ${f.full?'full':''}">${esc(f.label)}${f.required?' *':''}${control}${f.kind==='password'&&r.id?'<small>Leave blank to keep the current value.</small>':''}</label>`}
function editForm(type,id='',preset={}){const r=id?structuredClone(rec(id)):{orgId:scope||ofType('organizations')[0]?.id,...(type==='racks'?{units:42}:type==='purchases'?{quantity:1,unitCost:0,currency:'USD',status:'Draft'}:type==='diagrams'?{nodes:[],edges:[]}:{}),...preset};if(!r){toast('Record unavailable');return}dialogRecord=r;const orgRequired=!['organizations','vendors','templates'].includes(type);modal(`${id?'Edit':'New'} ${type==='articles'?'article':type==='passwords'?'credential':type==='purchases'?'purchase order':names[type].toLowerCase().replace(/s$/,'')}`,`<form id="record-form" data-type="${type}" data-id="${id}"><div class="form-grid"><label class="form-field">${type==='articles'?'Article title':'Name'} *<input name="name" value="${esc(r.name||'')}" required maxlength="200"></label>${orgRequired?`<label class="form-field">Organization *<select name="orgId" required id="form-org"><option value="">Select organization</option>${ofType('organizations').map(o=>`<option value="${o.id}" ${r.orgId===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>`:''}${schema[type].map(f=>fieldHtml(f,r,type)).join('')}<div id="custom-fields" class="full">${customFields(r)}</div>${type!=='passwords'&&orgRequired?`<label class="form-field">Visibility<select name="visibility"><option value="internal" ${r.visibility!=='client'?'selected':''}>Internal only</option><option value="client" ${r.visibility==='client'?'selected':''}>Client visible</option></select><small>Client users see only assigned organizations.</small></label>`:''}<label class="form-field full">Notes<textarea name="notes" maxlength="30000">${esc(r.notes||'')}</textarea></label>${type!=='templates'&&type!=='vendors'?`<label class="form-field full">Related records<select multiple name="relatedIds" aria-label="Related records">${records.filter(v=>v.id!==id&&v.type!=='organizations'&&v.orgId===r.orgId).map(v=>`<option value="${v.id}" ${(r.relatedIds||[]).includes(v.id)?'selected':''}>${esc(names[v.type]+' · '+v.name)}</option>`).join('')}</select><small>Hold Ctrl or Command to select multiple records.</small></label>`:''}</div><div class="form-actions"><button type="button" data-act="close">Cancel</button><button class="primary" type="submit">${id?'Save changes':'Create record'}</button></div></form>`,type==='articles'?'wide':'');dialogRecord=r}
function customFields(r){const template=rec(r.templateId);if(!template)return '';return `<div class="form-section">${esc(template.name)} fields</div><div class="form-grid" style="margin-top:15px">${template.fields.map((name,i)=>`<label class="form-field">${esc(name)}<input data-custom-key="${esc(name)}" name="custom_${i}" value="${esc(r.customFields?.[name]||'')}" maxlength="2000"></label>`).join('')}</div>`}
function markdown(text){const source=String(text||'').replace(/\r/g,'');let inCode=false,html='',list='';const endList=()=>{if(list){html+=`</${list}>`;list=''}};for(const line of source.split('\n')){if(line.startsWith('```')){endList();html+=inCode?'</code></pre>':'<pre><code>';inCode=!inCode;continue}if(inCode){html+=esc(line)+'\n';continue}const safe=esc(line).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');const h=/^(#{1,3}) (.*)/.exec(safe);if(h){endList();html+=`<h${h[1].length}>${h[2]}</h${h[1].length}>`;continue}const li=/^(?:[-*] |\d+\. )(.*)/.exec(safe);if(li){const type=/^\d/.test(safe)?'ol':'ul';if(list!==type){endList();html+=`<${type}>`;list=type}html+=`<li>${li[1]}</li>`}else{endList();if(safe.trim())html+=`<p>${safe}</p>`}}endList();if(inCode)html+='</code></pre>';return html}
async function detail(id){const r=await api('/records/'+id);dialogRecord=r;let meta=(schema[r.type]||[]).filter(f=>!['password','textarea','steps','lines'].includes(f.kind)&&r[f.key]!==undefined&&r[f.key]!==''&&f.key!=='templateId');let body=`<div class="actions">${badge(names[r.type])}${r.status?badge(r.status):''}${r.orgId?`<button class="text-button" data-record="${r.orgId}">${esc(title(r.orgId))}</button>`:''}<button class="text-button" data-act="favorite" data-id="${r.id}" data-active="${!r.favorite}">${icon('favorites')}${r.favorite?'Favorited':'Favorite'}</button>${writable()?`<button class="text-button" data-act="edit" data-id="${r.id}">${icon('edit')}Edit</button>`:''}</div>`;
 if(r.type==='passwords'){body+=`<div class="notice" style="margin-top:20px">Password access requires reauthentication and is written to the audit log.</div>${writable()?`<form id="reveal-form" data-id="${r.id}"><div class="form-grid"><label class="form-field">Your account password<input name="password" type="password" required autocomplete="current-password"></label>${user.mfa?'<label class="form-field">Authenticator code<input name="code" required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"></label>':''}</div><div class="form-actions"><button type="submit" class="primary">Reveal credential</button></div></form><div id="secret-area"></div>`:'<p class="muted">Your role cannot reveal vault secrets.</p>'}`}
 body+=`<div class="detail-meta">${meta.map(f=>`<div><small>${esc(f.label)}</small><strong>${f.kind==='ref'?`<button class="text-button" data-record="${esc(r[f.key])}">${esc(title(r[f.key]))}</button>`:f.kind==='date'?date(r[f.key]):f.kind==='url'&&/^https?:\/\//i.test(r[f.key])?`<a class="safe-link" href="${esc(r[f.key])}" target="_blank" rel="noopener noreferrer">${esc(r[f.key])}</a>`:esc(r[f.key])}</strong></div>`).join('')}${Object.entries(r.customFields||{}).map(([k,v])=>`<div><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div>`;
 if(r.type==='articles')body+=`<article class="article-content">${markdown(r.content)}</article>`;
 if(r.type==='procedures'){const done=r.steps.filter(s=>s.done).length;body+=`<div class="procedure-progress"><span>${done} / ${r.steps.length} completed</span><span class="bar"><i style="width:${r.steps.length?done/r.steps.length*100:0}%"></i></span></div>${r.steps.map((s,i)=>`<label class="procedure-step ${s.done?'done':''}"><input type="checkbox" data-step="${i}" ${s.done?'checked':''} ${writable()?'':'disabled'}><span>${esc(s.text)}</span></label>`).join('')}`}
 if(r.type==='templates')body+=`<div class="notice">Custom fields: ${(r.fields||[]).map(esc).join(', ')}</div>`;
 if(r.type==='networks'){const allocations=ofType('addresses').filter(a=>a.networkId===id);body+=`<div class="detail-section"><h3>IP allocations (${allocations.length})</h3>${allocations.map(a=>`<div class="mini-item"><span>${esc(a.address)} · ${esc(a.name)}</span><button class="text-button" data-record="${a.id}">Open</button></div>`).join('')||'<p class="muted">No IP addresses allocated yet.</p>'}${writable()?`<button data-act="network-address" data-id="${id}">Allocate IP address</button>`:''}</div>`}
 if(r.type==='purchases'){const action={Draft:'submit',Submitted:admin()?'approve':'',Approved:'order',Ordered:'receive'}[r.status];body+=`<div class="notice">Order total: <strong>${money(r.quantity*r.unitCost,r.currency)}</strong><br>Draft · Submitted · Approved · Ordered · Received</div>${writable()&&action?`<button class="primary" data-act="purchase" data-id="${id}" data-transition="${action}">${{submit:'Submit for approval',approve:'Approve order',order:'Mark as ordered',receive:'Receive devices into inventory'}[action]}</button>`:''}${writable()&&!['Received','Cancelled'].includes(r.status)?` <button data-act="purchase" data-id="${id}" data-transition="cancel">Cancel order</button>`:''}${r.receivedAssets?.length?`<h3 class="subheading">Received devices</h3><div class="file-list">${r.receivedAssets.map(a=>`<button data-record="${a}">${esc(title(a))}</button>`).join('')}</div>`:''}`}
 if(r.type==='diagrams')body+=`<div class="diagram-preview">${svgDiagram(r,false)}</div><button data-act="open-diagram" data-id="${id}">Open diagram editor</button>`;
 if(r.type==='racks')body+=`<button data-page="racks">View rack elevation</button>`;
 if(r.notes)body+=`<div class="article-content" style="margin-top:20px">${markdown(r.notes)}</div>`;
 const related=new Map();for(const other of records){if(other.id===id)continue;if((r.relatedIds||[]).includes(other.id)||(other.relatedIds||[]).includes(id)||['rackId','assetId','connectedAssetId','networkId','locationId','purchaseId','templateId','vendorId'].some(k=>other[k]===id)||r.type==='organizations'&&other.orgId===id)related.set(other.id,other)}if(related.size)body+=`<div class="detail-section"><h3>Linked documentation (${related.size})</h3><div class="file-list">${[...related.values()].map(o=>`<button data-record="${o.id}">${icon(o.type)}${esc(o.name)}</button>`).join('')}</div></div>`;
 body+=`<div class="detail-section"><h3>Attachments</h3><div class="file-list">${r.attachments.map(f=>`<span class="file-link"><a href="/api/attachments/${f.id}" download>${esc(f.name)}</a><small>${Math.ceil(f.size/1024)} KB</small>${writable()?`<button class="icon-button danger" data-act="delete-attachment" data-id="${f.id}" aria-label="Delete attachment">×</button>`:''}</span>`).join('')||'<small>No attachments.</small>'}</div>${writable()?'<label class="form-field" style="margin-top:15px">Attach a file (up to 5 MB)<input type="file" id="attachment-file"></label>':''}</div>`;
 if(user.role!=='client')body+=`<div class="detail-section"><h3>Team comments</h3>${r.comments.map(c=>`<div class="comment"><small>${esc(c.author)} · ${esc(when(c.created))}</small><p>${esc(c.body)}</p></div>`).join('')}${writable()?`<form id="comment-form" class="comment-form" data-id="${id}"><input name="body" required maxlength="5000" aria-label="Comment" placeholder="Add a note for your team…"><button type="submit">Post comment</button></form>`:''}</div>`;
 body+=`<div class="form-actions"><small style="margin-right:auto">Version ${r.version} · Updated ${esc(when(r.updated))}</small>${r.type!=='passwords'&&user.role!=='client'?`<button data-act="history" data-id="${id}">Version history</button>`:''}${writable()?`<button class="danger" data-act="delete" data-id="${id}">Move to recycle bin</button>`:''}</div>`;modal(r.name,body,r.type==='articles'?'wide':'');dialogRecord=r}
function drawDiagram(){if(page!=='diagrams'||!diagramDraft)return;const wrap=$('.diagram-wrap');if(wrap)wrap.innerHTML=svgDiagram(diagramDraft);const side=$('.diagram-layout>div:last-child');if(side)side.innerHTML=diagramSide();if($('#diagram-save-status'))$('#diagram-save-status').textContent=diagramDirty?'Unsaved changes':'All changes saved';bindDiagramDrag()}
let drag=null;
function bindDiagramDrag(){const svg=$('#diagram-svg');if(!svg)return;svg.onpointerdown=e=>{const group=e.target.closest('[data-node]');if(!group)return;selectedNode=group.dataset.node;const n=diagramDraft.nodes.find(n=>n.id===selectedNode);if(writable()){const point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());drag={id:n.id,dx:point.x-n.x,dy:point.y-n.y,svg,moved:false};e.preventDefault()}else drawDiagram()}}
document.addEventListener('pointermove',e=>{if(!drag||!diagramDraft)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(drag.svg.getScreenCTM().inverse()),n=diagramDraft.nodes.find(n=>n.id===drag.id);if(!n)return;n.x=Math.round(Math.max(0,Math.min(1800,p.x-drag.dx)));n.y=Math.round(Math.max(0,Math.min(1200,p.y-drag.dy)));drag.moved=true;diagramDirty=true;const group=[...drag.svg.querySelectorAll('[data-node]')].find(g=>g.dataset.node===n.id);group?.setAttribute('transform',`translate(${n.x},${n.y})`);drag.svg.querySelectorAll('.edge').forEach((g,i)=>{const edge=diagramDraft.edges[i],a=diagramDraft.nodes.find(n=>n.id===edge.from),b=diagramDraft.nodes.find(n=>n.id===edge.to);if(!a||!b)return;g.querySelector('path').setAttribute('d',`M${a.x+160} ${a.y+39} C${a.x+210} ${a.y+39},${b.x-50} ${b.y+39},${b.x} ${b.y+39}`);const t=g.querySelector('text');t.setAttribute('x',(a.x+160+b.x)/2);t.setAttribute('y',(a.y+b.y)/2+22)})});
document.addEventListener('pointerup',()=>{if(drag){drag=null;drawDiagram()}});
function parseCSV(text){let rows=[],row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(value);value=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(v=>v.trim()))rows.push(row);row=[];value=''}else value+=c}if(quoted)throw Error('CSV contains an unclosed quoted field');row.push(value);if(row.some(v=>v.trim()))rows.push(row);if(rows.length<2)throw Error('CSV needs a header and at least one data row');const headers=rows.shift().map(v=>v.trim().replace(/^\uFEFF/,''));if(!headers.includes('name'))throw Error('CSV must include a name column');if(new Set(headers).size!==headers.length)throw Error('CSV headers must be unique');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error(`Row ${i+2} has a different number of columns`);return Object.fromEntries(headers.map((k,n)=>[k,r[n].trim()]))})}
function exportCSV(type){const rows=listRows(type),keys=['name','orgId',...(schema[type]||[]).filter(f=>!['password','steps','lines','textarea'].includes(f.kind)).map(f=>f.key),'notes'];const encode=v=>'"'+String(v??'').replaceAll('"','""')+'"';download([keys.map(encode).join(','),...rows.map(r=>keys.map(k=>encode(/^[=+@\-\t\r]/.test(String(r[k]||''))?"'"+r[k]:r[k])).join(','))].join('\r\n'),`trinetra-${type}.csv`,'text/csv;charset=utf-8')}
async function history(id){const r=rec(id),versions=await api('/records/'+id+'/versions');modal('Version history — '+r.name,versions.map(v=>`<details class="version-item"><summary>Version ${v.version} · ${esc(v.actor)} · ${esc(when(v.time))}</summary><pre>${esc(JSON.stringify(v.data,null,2))}</pre>${writable()&&!['passwords','purchases'].includes(r.type)&&v.version!==r.version?`<button data-act="revert" data-id="${id}" data-version="${v.version}" data-current="${r.version}">Restore this version</button>`:''}</details>`).join(''))}
function userForm(id){const u=id?window.managedUsers.find(u=>u.id===id):{};modal(id?'Edit user access':'Create user',`<form id="user-form" data-id="${id||''}"><div class="form-grid">${!id?'<label class="form-field">Full name<input name="name" required maxlength="120"></label><label class="form-field">Email<input name="email" type="email" required></label><label class="form-field full">Initial password<input name="password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"><small>Share through a secure channel. The user can change it in Settings.</small></label>':''}<label class="form-field">Role<select name="role">${['editor','viewer','client','admin'].map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></label>${id?`<label class="form-field">Account status<select name="active"><option value="true" ${u.active?'selected':''}>Active</option><option value="false" ${!u.active?'selected':''}>Disabled</option></select></label>`:''}<label class="form-field full">Assigned organizations<select name="orgs" multiple>${ofType('organizations').map(o=>`<option value="${o.id}" ${(u.orgs||[]).includes(o.id)?'selected':''}>${esc(o.name)}</option>`).join('')}</select><small>Empty means all organizations for editors/viewers. Clients require at least one. Administrators always have full access. Hold Ctrl/Command for multiple selections.</small></label></div><div class="form-actions"><button type="button" data-act="close">Cancel</button><button type="submit" class="primary">${id?'Save access':'Create user'}</button></div></form>`)}
async function tokens(){const rows=await api('/tokens');modal('Read-only API tokens',`<div class="notice">Tokens expire after 30 days and cannot reveal credentials or change data.</div>${rows.map(t=>`<div class="mini-item"><div><strong>${esc(t.name)}</strong><small>Expires ${esc(when(t.expires))}</small></div><button data-act="revoke-token" data-id="${t.id}">Revoke</button></div>`).join('')}<form id="token-form" class="comment-form" style="margin-top:20px"><input name="name" required aria-label="Token name" placeholder="Integration name"><button type="submit" class="primary">Create token</button></form>`)}
async function saveDiagram(){if(!diagramDraft)return;const result=await api('/records/'+diagramId,'PUT',diagramDraft);diagramDraft={...diagramDraft,...result};diagramDirty=false;await load();close();if(page==='diagrams')drawDiagram();toast('Diagram saved')}
async function action(act,b){const id=b.dataset.id;
 if(act==='close')return close();if(act==='menu'){document.body.classList.toggle('menu-open');return}
 if(act==='logout'){if(diagramDirty){modal('Unsaved diagram','<p class="subtitle">Save your diagram before signing out.</p><div class="form-actions"><button data-act="close">Keep editing</button><button class="primary" data-act="save-diagram">Save diagram</button></div>','small');return}await api('/logout','POST',{});user=null;csrf='';records=[];close();authScreen();return}
 if(act==='new')return editForm(b.dataset.type);if(act==='edit')return editForm(rec(id).type,id);
 if(act==='favorite'){await api(`/records/${id}/favorite`,'POST',{active:b.dataset.active==='true'});favorites=await api('/favorites');await detail(id);if(page==='favorites')await render();return}
 if(act==='delete'){return modal('Move record to recycle bin?',`<p class="subtitle">${esc(rec(id)?.name)} can be restored later. Records with active links must be unlinked first.</p><div class="form-actions"><button data-act="close">Cancel</button><button class="danger" data-act="confirm-delete" data-id="${id}">Move to recycle bin</button></div>`,'small')}
 if(act==='confirm-delete'){await api('/records/'+id,'DELETE',{});close();await load();if(diagramId===id){diagramDraft=null;diagramDirty=false}await render();toast('Record moved to recycle bin');return}
 if(act==='restore'){await api(`/records/${id}/restore`,'POST',{});await load();await render();toast('Record restored');return}
 if(act==='history')return history(id);if(act==='revert'){await api(`/records/${id}/revert`,'POST',{targetVersion:Number(b.dataset.version),version:Number(b.dataset.current)});await load();await render();await detail(id);toast('Version restored as a new revision');return}
 if(act==='purchase'){const r=rec(id),transition=b.dataset.transition;modal(transition==='receive'?'Receive devices into inventory?':'Update purchase order?',`<p class="subtitle">${transition==='receive'?`Create ${Number(r.quantity)} inventory devices linked to ${esc(r.name)}.`:`Mark ${esc(r.name)} as ${esc({submit:'Submitted',approve:'Approved',order:'Ordered',cancel:'Cancelled'}[transition])}.`}</p><div class="notice" style="margin-top:20px">This records an internal workflow step. It does not send an order to a vendor or make a payment.</div><div class="form-actions"><button data-act="close">Back</button><button class="primary" data-act="confirm-purchase" data-id="${id}" data-transition="${transition}" data-version="${r.version}">Confirm ${transition==='receive'?'receipt':'status'}</button></div>`,'small');return}
 if(act==='confirm-purchase'){await api(`/records/${id}/purchase`,'POST',{action:b.dataset.transition,version:Number(b.dataset.version)});await load();await render();await detail(id);toast('Purchase order updated');return}
 if(act==='rack-asset'){const rack=rec(id);return editForm('assets','',{orgId:rack.orgId,rackId:id,rackUnits:1})}if(act==='network-address'){const n=rec(id);return editForm('addresses','',{orgId:n.orgId,networkId:id})}
 if(act==='delete-attachment'){const recordId=dialogRecord.id;await api('/attachments/'+id,'DELETE',{});await detail(recordId);toast('Attachment removed');return}
 if(act==='generate'){const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*',bytes=new Uint8Array(80);crypto.getRandomValues(bytes);const password=[...bytes].filter(n=>n<Math.floor(256/alphabet.length)*alphabet.length).slice(0,24).map(n=>alphabet[n%alphabet.length]).join('');$('#record-form [name=password]').value=password;toast('Generated a 24-character password');return}
 if(act==='conceal'){clearTimeout(secretTimer);$('#secret-area').innerHTML='';return}
 if(act==='copy-secret'){await navigator.clipboard.writeText($('#revealed-secret').textContent);toast('Copied. Clipboard contents are managed by your operating system.');return}
 if(act==='prev'){pageNumber=Math.max(1,pageNumber-1);return render()}if(act==='next'){pageNumber++;return render()}
 if(act==='csv')return exportCSV(b.dataset.type);
 if(act==='import'){const type=b.dataset.type;if(['organizations','templates','passwords'].includes(type)){modal('CSV import',`<p class="subtitle">Create organizations and templates using their forms. CSV import is available for organization-owned asset, network, contact, and documentation records.</p><div class="form-actions"><button data-act="close">Got it</button></div>`,'small');return}const keys=['name',...(schema[type]||[]).filter(f=>!['ref','password','steps','lines'].includes(f.kind)).map(f=>f.key)];modal('Import '+names[type].toLowerCase(),`<form id="import-form" data-type="${type}"><label class="form-field">Organization<select name="orgId" required><option value="">Select organization</option>${ofType('organizations').map(o=>`<option value="${o.id}" ${scope===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label><p class="import-help">CSV columns use field keys. Required: name, plus required fields for this record type. Linked fields must use record IDs. Up to 500 records; the entire import is validated before saving.</p><div class="code-block">${keys.map(esc).join(',')}</div><label class="form-field" style="margin-top:15px">Choose CSV file<input type="file" id="csv-file" accept=".csv,text/csv"></label><label class="form-field" style="margin-top:15px">Or paste CSV<textarea name="csv" required style="min-height:180px"></textarea></label><div class="form-actions"><button type="button" data-act="close">Cancel</button><button class="primary" type="submit">Validate and import</button></div></form>`);return}
 if(act==='export'){const data=await api('/export');download(JSON.stringify(data,null,2),'trinetra-documentation.json');toast('Documentation exported; credentials excluded');return}
 if(act==='report-export'){const data={generatedAt:new Date().toISOString(),organization:scope||'all',assets:ofType('assets').filter(inScope),purchases:ofType('purchases').filter(inScope),expirations:expirations().map(v=>({name:v.r.name,org:title(v.r.orgId),type:v.kind,due:v.date,days:days(v.date)}))};download(JSON.stringify(data,null,2),'trinetra-report.json');return}
 if(act==='audit-export')return download(JSON.stringify(window.auditRows,null,2),'trinetra-audit.json');
 if(act==='new-user')return userForm();if(act==='edit-user')return userForm(id);
 if(act==='change-password'){modal('Change your password','<form id="password-form"><div class="form-grid"><label class="form-field full">Current password<input name="current" type="password" required autocomplete="current-password"></label><label class="form-field full">New password<input name="password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><label class="form-field full">Confirm new password<input name="confirm" type="password" required minlength="12" autocomplete="new-password"></label></div><div class="form-actions"><button type="button" data-act="close">Cancel</button><button class="primary" type="submit">Change password</button></div></form>','small');return}
 if(act==='mfa'){modal(user.mfa?'Disable authenticator MFA':'Set up authenticator MFA',`<form id="mfa-${user.mfa?'disable':'start'}-form"><label class="form-field">Your account password<input name="password" type="password" required autocomplete="current-password"></label>${user.mfa?'<label class="form-field" style="margin-top:15px">Current authenticator code<input name="code" required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"></label>':''}<div class="form-actions"><button type="button" data-act="close">Cancel</button><button class="primary" type="submit">${user.mfa?'Disable MFA':'Continue'}</button></div></form>`,'small');return}
 if(act==='tokens')return tokens();if(act==='revoke-token'){await api('/tokens/'+id,'DELETE',{});await tokens();toast('API token revoked');return}
 if(act==='open-diagram'){close();diagramDraft=structuredClone(rec(id));diagramId=id;diagramDirty=false;navigation('diagrams');return}
 if(act==='save-diagram')return saveDiagram();if(act==='discard-diagram'){diagramDirty=false;if(b.dataset.diagramTarget){diagramId=b.dataset.diagramTarget;diagramDraft=structuredClone(rec(diagramId));close();return render()}return navigation(b.dataset.pageTarget)}
 if(act==='deselect-node'){selectedNode='';return drawDiagram()}
 if(act==='remove-node'){diagramDraft.nodes=diagramDraft.nodes.filter(n=>n.id!==selectedNode);diagramDraft.edges=diagramDraft.edges.filter(e=>e.from!==selectedNode&&e.to!==selectedNode);selectedNode='';diagramDirty=true;return drawDiagram()}
 if(act==='remove-edge'){diagramDraft.edges.splice(Number(b.dataset.index),1);diagramDirty=true;return drawDiagram()}
 if(act==='svg-export'){const markup=svgDiagram(diagramDraft,false);download(markup,diagramDraft.name.replace(/[^a-z0-9-]/gi,'-')+'.svg','image/svg+xml');return}
}
document.addEventListener('click',async e=>{try{const button=e.target.closest('[data-act],[data-record],[data-page]');if(button){e.preventDefault();if(button.dataset.page)return navigation(button.dataset.page);if(button.dataset.record)return await detail(button.dataset.record);if(button.dataset.act){button.disabled=true;try{await action(button.dataset.act,button)}finally{button.disabled=false}}}if(e.target===$('#overlay'))close();if(!e.target.closest('.searchbox,#search-results')&&$('#search-results'))$('#search-results').hidden=true}catch(error){toast(error.message)}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]');if(button)button.disabled=true;form.querySelector('.form-error')?.remove();const data=Object.fromEntries(new FormData(form));try{
 if(form.id==='auth-form'){const setup=form.dataset.setup==='true';const result=await api(setup?'/setup':'/login','POST',{...data,samples:!!form.querySelector('[name=samples]')?.checked});user=result.user;csrf=result.csrf;await load();page='dashboard';await render()}
 if(form.id==='record-form'){const type=form.dataset.type,id=form.dataset.id;let body={...dialogRecord,...data,type};body.relatedIds=new FormData(form).getAll('relatedIds');if(!['organizations','templates','vendors'].includes(type)&&!data.orgId)throw Error('Select an organization');for(const f of schema[type]){if(f.kind==='number'&&data[f.key]!=='')body[f.key]=Number(data[f.key]);if(f.kind==='password'&&id&&!data[f.key])delete body[f.key];if(f.kind==='steps')body.steps=String(data.steps||'').split('\n').map(s=>s.trim()).filter(Boolean).map(text=>({text,done:dialogRecord.steps?.find(s=>s.text===text)?.done||false}));if(f.kind==='lines')body.fields=String(data.fields||'').split('\n').map(s=>s.trim()).filter(Boolean)}if(type==='passwords'&&!id&&!body.password)throw Error('Enter or generate a password');body.customFields=Object.fromEntries([...form.querySelectorAll('[data-custom-key]')].map(el=>[el.dataset.customKey,el.value]));for(const k of Object.keys(body))if(k.startsWith('custom_'))delete body[k];if(type==='diagrams'){body.nodes=dialogRecord.nodes||[];body.edges=dialogRecord.edges||[]}const result=await api('/records'+(id?'/'+id:''),id?'PUT':'POST',body);if(type==='diagrams'){diagramId=result.id;diagramDraft=structuredClone(result);diagramDirty=false}close();await load();await render();toast(id?'Changes saved':'Record created');if(type==='diagrams')navigation('diagrams')}
 if(form.id==='reveal-form'){const secret=await api(`/records/${form.dataset.id}/reveal`,'POST',data);form.reset();$('#secret-area').innerHTML=`<div class="secret"><div><code id="revealed-secret">${esc(secret.password)}</code><small>Automatically concealed in 30 seconds.</small>${secret.totp?`<p style="margin:10px 0 0">Authenticator: <code>${esc(secret.totp)}</code><small>Valid for ${secret.validFor} seconds.</small></p>`:''}</div><div class="actions"><button data-act="copy-secret">Copy</button><button data-act="conceal">Hide</button></div></div>`;secretTimer=setTimeout(()=>{if($('#secret-area'))$('#secret-area').innerHTML=''},30000)}
 if(form.id==='comment-form'){await api(`/records/${form.dataset.id}/comments`,'POST',data);await detail(form.dataset.id);toast('Comment added')}
 if(form.id==='user-form'){const id=form.dataset.id;await api('/users'+(id?'/'+id:''),id?'PUT':'POST',{...data,active:data.active==='true',orgs:new FormData(form).getAll('orgs')});close();await render();toast('User access saved')}
 if(form.id==='password-form'){if(data.password!==data.confirm)throw Error('New passwords do not match');const result=await api('/password','POST',data);csrf=result.csrf;user=result.user;close();toast('Password changed; other sessions signed out')}
 if(form.id==='mfa-start-form'){const result=await api('/mfa/start','POST',data);form.reset();modal('Connect your authenticator',`<div class="notice">In your authenticator app, add an account using a setup key. Choose time-based (TOTP), 6 digits, and a 30-second period. Keep this key private.</div><label class="form-field">Setup key<div class="code-block" style="margin-top:8px">${esc(result.seed)}</div></label><form id="mfa-confirm-form" style="margin-top:20px"><label class="form-field">Six-digit code<input name="code" required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"></label><div class="form-actions"><button type="button" data-act="close">Cancel</button><button class="primary" type="submit">Enable MFA</button></div></form>`,'small')}
 if(form.id==='mfa-confirm-form'){await api('/mfa/confirm','POST',data);user=(await api('/me')).user;close();await render();toast('MFA enabled')}
 if(form.id==='mfa-disable-form'){await api('/mfa/disable','POST',data);user=(await api('/me')).user;close();await render();toast('MFA disabled')}
 if(form.id==='token-form'){const t=await api('/tokens','POST',data);modal('API token created',`<div class="notice warning">Copy this token now. It will not be displayed again. Keep it out of documentation records and source code.</div><div class="code-block">${esc(t.token)}</div><small>Expires ${esc(when(t.expires))}</small><div class="form-actions"><button data-act="tokens">Back to token list</button><button class="primary" data-act="close">Done</button></div>`,'small')}
 if(form.id==='import-form'){const parsed=parseCSV(data.csv).map(r=>({...r,type:form.dataset.type,orgId:data.orgId}));if(form.dataset.type==='procedures')for(const r of parsed)r.steps=String(r.steps||'').split('|').filter(Boolean).map(text=>({text,done:false}));const result=await api('/import','POST',{records:parsed});close();await load();await render();toast(`${result.records.length} records imported`)}
 if(form.id==='node-form'){const node={label:data.label,kind:data.kind,assetId:data.assetId||undefined};if(selectedNode)Object.assign(diagramDraft.nodes.find(n=>n.id===selectedNode),node);else{selectedNode=crypto.randomUUID();diagramDraft.nodes.push({...node,id:selectedNode,x:80+(diagramDraft.nodes.length%4)*250,y:90+Math.floor(diagramDraft.nodes.length/4)*140})}diagramDirty=true;drawDiagram()}
 if(form.id==='edge-form'){if(data.from===data.to)throw Error('Choose two different components');if(diagramDraft.edges.some(v=>v.from===data.from&&v.to===data.to&&v.label===data.label))throw Error('This connection already exists');diagramDraft.edges.push(data);diagramDirty=true;drawDiagram()}
 }catch(error){if(form.isConnected)errorIn(form,error);else toast(error.message)}finally{if(button)button.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='list-search'){query=e.target.value;pageNumber=1;const pos=e.target.selectionStart;render();const input=$('#list-search');input?.focus();input?.setSelectionRange(pos,pos)}if(e.target.id==='global-search'){clearTimeout(searchTimer);const term=e.target.value.trim(),request=++searchRequest;if(!term){$('#search-results').hidden=true;return}searchTimer=setTimeout(async()=>{try{const results=await api('/records?q='+encodeURIComponent(term));if(request!==searchRequest||!$('#search-results'))return;$('#search-results').hidden=false;$('#search-results').innerHTML=results.filter(inScope).slice(0,15).map(r=>`<button data-record="${r.id}">${esc(r.name)}<small>${names[r.type]} · ${esc(title(r.orgId))}</small></button>`).join('')||'<div class="empty">No matching records.</div>'}catch(e){toast(e.message)}},150)}});
document.addEventListener('change',async e=>{try{
 if(e.target.id==='scope'){if(diagramDirty){e.target.value=scope;toast('Save the diagram before changing organization scope');return}scope=e.target.value;pageNumber=1;diagramDraft=null;render()}
 if(e.target.id==='status-filter'){filter=e.target.value;pageNumber=1;render()}
 if(e.target.id==='diagram-select'){const id=e.target.value;if(diagramDirty){e.target.value=diagramId;modal('Unsaved diagram changes','<p class="subtitle">Save your changes or discard them before opening another diagram.</p><div class="form-actions"><button data-act="close">Keep editing</button><button data-act="discard-diagram" data-diagram-target="'+esc(id)+'">Discard changes</button><button class="primary" data-act="save-diagram">Save diagram</button></div>','small');return}diagramId=id;diagramDraft=structuredClone(rec(id));selectedNode='';render()}
 if(e.target.id==='form-org'){const type=$('#record-form').dataset.type;for(const f of schema[type].filter(f=>f.kind==='ref')){const el=$(`#record-form [name="${f.key}"]`);if(el){const options=ofType(f.ref).filter(v=>!v.orgId||v.orgId===e.target.value);el.innerHTML='<option value="">Select '+esc(f.label.toLowerCase())+'</option>'+options.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}}const links=$('#record-form [name=relatedIds]');if(links)links.innerHTML=records.filter(v=>v.orgId===e.target.value&&v.id!==dialogRecord.id).map(v=>`<option value="${v.id}">${esc(names[v.type]+' · '+v.name)}</option>`).join('');$('#custom-fields').innerHTML=''}
 if(e.target.name==='templateId'&&e.target.closest('#record-form')){$('#custom-fields').innerHTML=customFields({...dialogRecord,templateId:e.target.value})}
 if(e.target.id==='csv-file'){const f=e.target.files[0];if(f){if(f.size>5*1024*1024)throw Error('CSV file limit is 5 MB');$('#import-form [name=csv]').value=await f.text()}}
 if(e.target.id==='attachment-file'){const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024)throw Error('File limit is 5 MB');const id=dialogRecord.id;const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let start=0;start<bytes.length;start+=8192)binary+=String.fromCharCode(...bytes.subarray(start,start+8192));await api(`/records/${id}/attachments`,'POST',{name:f.name,mime:f.type,content:btoa(binary)});await detail(id);toast('Attachment uploaded')}
 if(e.target.hasAttribute('data-step')){const index=Number(e.target.dataset.step),r=dialogRecord,steps=structuredClone(r.steps);steps[index].done=e.target.checked;const body={...r,steps,status:steps.every(s=>s.done)?'Completed':'In progress'};await api('/records/'+r.id,'PUT',body);await load();await render();await detail(r.id)}
 }catch(error){toast(error.message)}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#global-search')?.focus()}if(e.key==='Escape'){close();if($('#search-results'))$('#search-results').hidden=true;document.body.classList.remove('menu-open')}if(e.key==='Enter'&&e.target.matches('[data-record]')){e.preventDefault();detail(e.target.dataset.record).catch(error=>toast(error.message))}if(e.key==='Enter'&&e.target.matches('[data-node]')){selectedNode=e.target.dataset.node;drawDiagram()}if(e.key==='Tab'&&!$('#overlay').hidden){const els=[...$('#dialog').querySelectorAll('button,input,textarea,select,a[href],summary')].filter(el=>!el.disabled&&el.getClientRects().length);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus()}}});
window.addEventListener('beforeunload',e=>{if(diagramDirty){e.preventDefault();e.returnValue=''}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(names[p]&&p!==page&&user)navigation(p)});
async function boot(){try{const status=await api('/status');workspaceTimeZone=status.timeZone||workspaceTimeZone;if(status.setupRequired)return authScreen(true);const me=await api('/me');if(!me)return authScreen();user=me.user;csrf=me.csrf;await load();const hash=location.hash.slice(1);if(names[hash])page=hash;await render()}catch(error){$('#root').innerHTML=`<div class="empty"><strong>Unable to open the workspace</strong>${esc(error.message)}<p>Check that the server is running, then refresh this page.</p></div>`}}
boot();
